/* eslint-disable react-hooks/exhaustive-deps */
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { Col, Row, Icon, Button, Table, Spin, Alert } from 'antd'
import React, { useEffect, useState } from 'react'
import PermissionCheckerV2 from '../../../../../../components/permissionCheckerV2'
import { RowWithMargin } from '../../../CommonComponents/index'
import { EbSectionWrapper } from '../../../CommonComponents'
import { useInsurerSummary } from '../../../state/InsurerSummary/hooks/useInsurerSummary'
import AddInsurerForm from './components/addInsurerForm'
import Filters from './components/filters'
import { insurerSummaryColumns } from './utility'
import { ColTextAlignRight } from '../../../CommonComponents/index.style'
import ExportExcel from '../../../components/ExportExcel'
import ebUrls from '../../../../../../request/urls/employeeBenefit'

const InsurerSummary = () => {
  const { insurerSummaryRequest, insurerSummaryData } = useInsurerSummary()
  const [{ INSURER_SUMMARY_LOADER }] = useLoaderContextValue()
  const [{ INSURER_SUMMARY_ERROR, insurerSummaryStatus }] = useErrorContextValue()
  const [addInsurerVisibility, toggleAddInsurerVisibility] = useState(false)
  const [listMetaData, setListMetaData] = useState({})
  const { resetError } = useResetError()
  const [filters, setFilters] = useState()

  const handleTableChange = (params) => {
    const query = {
      page: params.current,
      per_page: params.pageSize
    }
    insurerSummaryRequest({ ...query, ...filters })
  }

  useEffect(() => {
    if (insurerSummaryData && insurerSummaryData.meta_data) {
      setListMetaData(insurerSummaryData.meta_data)
    }
  }, [insurerSummaryData])

  useEffect(() => {
    if (INSURER_SUMMARY_ERROR) {
      setFilters()
      resetError(['INSURER_SUMMARY_ERROR'])
    }
  }, [INSURER_SUMMARY_ERROR])

  useEffect(() => {
    insurerSummaryRequest({ ...filters })
  }, [])
  return (
    <Spin spinning={!!INSURER_SUMMARY_LOADER}>
      {INSURER_SUMMARY_ERROR && <Alert type='error' message={insurerSummaryStatus} banner />}
      <EbSectionWrapper>
        <Row gutter={16}>
          <Col span={12}><h2>Insurer Summary</h2></Col>
          <ColTextAlignRight span={12}>
            <PermissionCheckerV2 requiredPermission='ops.eb_create_insurer'>
              <Button
                type='primary'
                onClick={() => toggleAddInsurerVisibility(true)}
              >
                Add Insurer <Icon type='plus' />
              </Button>
            </PermissionCheckerV2>
          </ColTextAlignRight>
        </Row>
        <Filters onFilter={setFilters} />
      </EbSectionWrapper>
      <EbSectionWrapper>
        <RowWithMargin>
          <ColTextAlignRight span={24}>
            <ExportExcel
              url={ebUrls.exportInsurerSummary}
              queryParams={filters}
              disabled={!insurerSummaryData?.data?.length}
            />
          </ColTextAlignRight>
        </RowWithMargin>
        <Table
          rowKey={({ insurance_provider: insuranceProvider }) => insuranceProvider}
          columns={insurerSummaryColumns({ currentPage: listMetaData.page })}
          dataSource={insurerSummaryData && insurerSummaryData.data ? insurerSummaryData.data : []}
          bordered
          onChange={handleTableChange}
          pagination={{
            pageSize: listMetaData.page_size,
            total: listMetaData.total_records,
            current: listMetaData.page
          }}
        />
      </EbSectionWrapper>
      {addInsurerVisibility && <AddInsurerForm onCancel={() => toggleAddInsurerVisibility(false)} />}
    </Spin>
  )
}
export default InsurerSummary
