import React from 'react'
import { Col, Form, DatePicker, Button, Icon } from 'antd'
import { RowWithMargin } from '../../../../CommonComponents'
import { horizontalLayout } from '../../../../utils/formLayout'
import { useInsurerSummary } from '../../../../state/InsurerSummary/hooks/useInsurerSummary'

const { RangePicker } = DatePicker
const { Item } = Form

const Filters = ({ form, onFilter, ...props }) => {
  const { getFieldDecorator } = form
  const { insurerSummaryRequest } = useInsurerSummary()

  const handleResetFilter = () => {
    onFilter()
    form.resetFields()
    insurerSummaryRequest()
  }

  const handleSubmit = (e) => {
    e.preventDefault()
    const { date_range: dateRange } = form.getFieldsValue()
    if (Array.isArray(dateRange) && dateRange.length) {
      const toBeSentValues = {
        updated_at_start_date: Array.isArray(dateRange) && dateRange[0].format('YYYY-MM-DD'),
        updated_at_end_date: Array.isArray(dateRange) && dateRange[1].format('YYYY-MM-DD')
      }
      insurerSummaryRequest(toBeSentValues)
      onFilter(toBeSentValues)
    }
  }
  return (
    <>

      <Form
        onSubmit={handleSubmit}
        {...horizontalLayout}
        labelCol={{ xs: 24, sm: 6 }}
      >
        <RowWithMargin gutter={8}>

          <Col span={12}>
            <Item
              label='Date Range'
              labelAlign='left'
            >
              {
                getFieldDecorator('date_range', {})(
                  <RangePicker allowClear />
                )
              }
            </Item>
          </Col>
          <Col span={4}>
            <Item>
              <Button
                type='primary'
                htmlType='submit'
              >
                Apply filter <Icon type='filter' />
              </Button>
            </Item>
          </Col>
          <Col span={4}>
            <Item>
              <Button
                type='danger'
                onClick={handleResetFilter}
              >
                Clear filter <Icon type='delete' />
              </Button>
            </Item>
          </Col>
        </RowWithMargin>
      </Form>
    </>
  )
}
export default Form.create({ name: 'insurer-filter' })(Filters)
