import ebUrls from '../../../../../request/urls/employeeBenefit'

const actions = {

  // COMPANY_DETAIL: 'COMPANY_DETAIL',
  INSURER_SUMMARY_REQUEST: 'INSURER_SUMMARY_REQUEST',
  INSURER_SUMMARY: 'INSURER_SUMMARY',
  ADD_INSUER_REQUEST: 'ADD_INSURER_REQUEST',
  ADD_INSUER: 'ADD_INSURER',

  getInsurerSummary: (payload) => ({
    type: actions.INSURER_SUMMARY_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.getInsurerSummary
    }
  }),
  addInsurer: (payload) => ({
    type: actions.ADD_INSUER_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: ebUrls.addInsurer
    }
  })
}

export default actions
