import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useEBContextValue } from '../../../context/index'
import actions from '../actions'

export const useInsurerSummary = () => {
  const [{ insurerSummaryData }, dispatch] = useEBContextValue()
  const [callApi] = useServiceRequest(dispatch)
  const insurerSummaryRequest = (payload = {}) => {
    callApi(actions.getInsurerSummary({ query: payload }))
  }
  return { insurerSummaryData, insurerSummaryRequest }
}

export const useAddInsurer = () => {
  const [{ addInsurerData }, dispatch] = useEBContextValue()
  const [callApi] = useServiceRequest(dispatch)
  const addInsurerRequest = (payload = {}) => {
    callApi(actions.addInsurer({ body: payload }))
  }
  return { addInsurerData, addInsurerRequest }
}
