import React, { useEffect } from 'react'
import { Alert, Col, Form, Input, message, Modal, Row, Spin } from 'antd'
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { useAddInsurer } from '../../../../state/InsurerSummary/hooks/useInsurerSummary'

const FORM_FIELDS = {
  INSURER_NAME: 'name'
}

const AddInsurer = ({ form, onCancel }) => {
  const { getFieldDecorator, setFieldsValue, getFieldsValue, setFields } = form
  const { addInsurerRequest } = useAddInsurer()
  const { resetError } = useResetError()
  const [{ ADD_INSURER_LOADER }] = useLoaderContextValue()
  const [{ ADD_INSURER_ERROR, addInsurerErrorData, addInsurerStatus }] = useErrorContextValue()

  const handleSubmit = () => {
    form.validateFields((error, values) => {
      if (!error) {
        addInsurerRequest(values)
      }
    })
  }

  useEffect(() => {
    if (ADD_INSURER_ERROR && addInsurerErrorData) {
      const { error } = addInsurerErrorData
      const values = getFieldsValue()
      setFieldsValue()
      for (const key in error) {
        setFields({
          [key]: {
            value: values[key],
            errors: Array.isArray(error[key]) && error[key].map(err => new Error(err))
          }
        })
      }
    }
  }, [addInsurerErrorData, getFieldsValue, setFieldsValue, setFields, ADD_INSURER_ERROR])

  useEffect(() => {
    if (addInsurerStatus === 'success') {
      message.success('Insurer added successfully')
      resetError([
        'addInsurerStatus'
      ])
      onCancel()
    }
  }, [addInsurerStatus, resetError, onCancel])

  return (
    <Modal
      visible
      title='Add Insurer'
      onCancel={onCancel}
      onOk={handleSubmit}
      okText='Submit'
    >
      <Spin spinning={!!ADD_INSURER_LOADER}>
        {ADD_INSURER_ERROR && (!addInsurerErrorData) && <Alert type='error' message={addInsurerStatus} banner />}
        <Row>
          <Col>
            <Form.Item
              hasFeedback
              label='Insurer Name'
            >
              {
                getFieldDecorator(FORM_FIELDS.INSURER_NAME, {})(
                  <Input />
                )
              }
            </Form.Item>
          </Col>
        </Row>
      </Spin>
    </Modal>
  )
}
export default Form.create({ name: 'add-insurer' })(AddInsurer)
